<script setup lang="ts">
import {computed,ref,onMounted,watch} from 'vue'
import FrozenSources from '../../components/FrozenSources.vue'
import {useViewScope} from '../../stores/view-scope'
import type {components} from '@adc/contracts'
import {createProtectedClient} from '../../api/protected'
import {ApiFailure} from '../../api/http'
import {useAuthenticationStore} from '../../stores/authentication'
type Metric=components['schemas']['AnalysisView']['metric'];type Analysis=components['schemas']['AnalysisView']
const api=createProtectedClient(),auth=useAuthenticationStore(),busy=ref(false),error=ref(''),result=ref<Analysis|null>(null),source=ref<components['schemas']['PerformanceSource']|null>(null),metric=ref<Metric>('cancellations'),clinic=ref(''),dentist=ref(''),treatment=ref('')
const scope=useViewScope(),catalogs=ref<Record<string,{id:string;label:string}[]>>({clinics:[],dentists:[],treatments:[]})
clinic.value=scope.clinic
watch(()=>scope.clinic,value=>{clinic.value=value;result.value=null;source.value=null})
onMounted(async()=>{busy.value=true;for(const kind of ['clinics','dentists','treatments'])try{let cursor:string|null=null;do{const page:{items:{id:string;label:string}[];next_cursor:string|null}=await api.get('/api/v1/'+kind+'?limit=100'+(cursor?'&cursor='+encodeURIComponent(cursor):''));catalogs.value[kind]!.push(...page.items);cursor=page.next_cursor}while(cursor)}catch{};try{await syncCutoff(true);await load()}catch(failure){await failed(failure);busy.value=false}})
const formatter=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}),local=(date:Date)=>formatter.format(date).replace(' ','T'),today=new Date(),start=ref(local(new Date(today.valueOf()-7*86400000))),end=ref(local(today)),cutoff=ref(today.toISOString())
const names:Record<Metric,string>={cancellations:'取消、爽约与未履约','treatment-comparison':'治疗单位加权比较','skill-slot-coverage':'治疗技能时隙覆盖','skill-structure':'有效资质结构',performance:'当前已发布绩效',coverage:'统一资料覆盖',traceability:'治疗七项要素追溯','calculation-time':'季度核算工作日耗时'},reasons:Record<string,string>={NATURAL_QUARTER_REQUIRED:'请选择完整自然季度，可使用“上一完整季度”快捷设置。',ZERO_DENOMINATOR:'暂无可统计记录，暂不能计算比例或均价。',SOURCE_SNAPSHOT_UNAVAILABLE:'该历史截止的来源状态无法可靠重建，请选用可核验的新截止或已冻结版本。',OPERATING_ROSTER_UNAVAILABLE:'缺少有来源、版本且覆盖该期间的营业诊所名单。',DATA_USAGE_EVIDENCE_INCOMPLETE:'缺少部分诊所统一患者、预约或治疗的使用证据，不能将缺失补为零。',WORKDAY_CALENDAR_UNAVAILABLE:'缺少有来源的工作日历及工作时间，暂不能计算工作日耗时。',COMPLETE_PUBLICATION_UNAVAILABLE:'没有该期间完整可比的已发布季度结果。',INCOMPLETE_PUBLICATION_BATCH:'同批次人员尚未全部发布，或发布口径不一致。',NO_COMPARABLE_CURRENT_PUBLICATION:'没有所选范围内可比的当前已发布结果。',UNPUBLISHED_OR_INCOMPARABLE_PEOPLE:'存在尚未发布或口径不可比的人员，请分别核实。',INCOMPLETE_APPOINTMENT_HISTORY:'预约状态证据不完整，不能确定该截止的队列。',TREATMENT_REQUIRED:'请选择一个已有治疗项目后查询技能覆盖。',DIFFERENT_TREATMENT_UNITS_NOT_COMPARABLE:'不同治疗的单位定义不能混合计算总均价；请分别查看明细或筛选单个项目。'}
const columns:Record<Metric,[string,string][]>={cancellations:[['clinic_id','诊所'],['ended_count','已结束队列'],['excluded_count','诊所原因排除'],['denominator','纳入统计的预约'],['patient_cancel_count','主动取消'],['no_show_count','已人工核实爽约'],['unprocessed_count','待人工处理'],['patient_cancel_rate','主动取消率'],['no_show_rate','爽约率'],['non_fulfillment_rate','未履约率']], 'treatment-comparison':[['clinic_id','诊所'],['treatment_id','治疗项目'],['count','次数'],['standard_units','标准单位合计'],['subtotal','金额合计'],['weighted_unit_price','加权单位价']], 'skill-slot-coverage':[['clinic_id','诊所'],['treatment_id','治疗项目'],['qualified_normal_slots','全部必需资质有效时隙'],['normal_slots','正常时隙总数'],['coverage','技能覆盖率']], 'skill-structure':[['dentist_id','牙医'],['qualification_id','资质'],['granted_date','生效日'],['expiry_date','到期日'],['verification_status','核验状态']], performance:[['dentist_id','牙医'],['quarter_start','季度起点'],['quarter_end','季度终点'],['calculation_status','版本状态'],['revenue','收入'],['medical_supply_cost','医疗用品'],['operating_expense','运营费用'],['net_profit','净利润'],['incentive_amount','个人激励']],coverage:[['clinic_id','营业诊所'],['patient_usage_evidence','患者资料使用证据'],['appointment_usage_evidence','预约使用证据'],['treatment_usage_evidence','治疗使用证据'],['unified_use','统一使用确认']],traceability:[['valid_treatment_count','有效治疗'],['seven_facts_complete_count','七项齐全'],['missing_elements','缺失要素']], 'calculation-time':[['ready_at','资料齐备时点'],['all_published_at','全部发布时点'],['working_days','工作日耗时'],['calendar_reference','日历来源']]}
const rows=computed(()=>(result.value?.rows??[]) as Record<string,unknown>[]),ratioMetrics=new Set<Metric>(['cancellations','skill-slot-coverage','coverage','traceability']),sourceAllowed=computed(()=>['sensitive.drilldown','cost.verify','getInvoice','resource.read'].every(cap=>auth.canAccess('HEADQUARTERS',cap)))
function percent(value:string){return new Intl.NumberFormat('zh-CN',{style:'percent',maximumFractionDigits:2}).format(Number(value))}
function display(key:string,value:unknown){if(value===null || value===undefined)return '—';if(typeof value==='boolean')return value?'已观察到':'未观察到';if(key.endsWith('_rate') || key==='coverage')return percent(String(value));if(['clinic_id','dentist_id','treatment_id'].includes(key)){const kind=key==='clinic_id'?'clinics':key==='dentist_id'?'dentists':'treatments';return catalogs.value[kind]?.find(r=>r.id===String(value))?.label??String(value)}if(key==='calculation_status' && value==='PUBLISHED')return '当前已发布';if(key==='verification_status' && value==='VERIFIED')return '已核验';if(typeof value==='object')return Object.keys(value).length?JSON.stringify(value):'无';return String(value)}
async function failed(failure:unknown){error.value=failure instanceof ApiFailure?`查询未完成：${failure.message}`:'查询暂不可用，请稍后重试。';if(failure instanceof ApiFailure && [401,403].includes(failure.status)){result.value=null;source.value=null;await auth.ensure()}}
async function syncCutoff(resetRange=false){const response=await api.getResource('/api/v1/me');const timestamp=response.serverDate?Date.parse(response.serverDate):NaN;if(!Number.isFinite(timestamp))throw new Error('Server time unavailable');cutoff.value=new Date(timestamp).toISOString();if(resetRange){start.value=local(new Date(timestamp-7*86400000));end.value=local(new Date(timestamp))}result.value=null;source.value=null}
async function updateCurrentCutoff(){busy.value=true;error.value='';try{await syncCutoff()}catch(failure){await failed(failure)}finally{busy.value=false}}
async function load(){busy.value=true;error.value='';result.value=null;source.value=null;try{const query=new URLSearchParams({start:`${start.value.length===16?start.value+':00':start.value}+08:00`,end:`${end.value.length===16?end.value+':00':end.value}+08:00`,cutoff:cutoff.value,rule_version:'A1a-B13'});if(clinic.value)query.set('clinic_id',clinic.value);if(dentist.value)query.set('dentist_id',dentist.value);if(treatment.value)query.set('treatment_id',treatment.value);result.value=await api.get(`/api/v1/analytics/${metric.value}?${query}`)}catch(failure){await failed(failure)}finally{busy.value=false}}
function changeMetric(){result.value=null;source.value=null;if(!['treatment-comparison','skill-slot-coverage','traceability'].includes(metric.value))treatment.value='';if(['coverage','calculation-time'].includes(metric.value))dentist.value=''}
function previousQuarter(){const month=Number(new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Shanghai',month:'numeric'}).format(today)),year=Number(new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Shanghai',year:'numeric'}).format(today)),until=new Date(Date.UTC(year,Math.floor((month-1)/3)*3,1)),from=new Date(Date.UTC(year,Math.floor((month-1)/3)*3-3,1));start.value=from.toISOString().slice(0,10)+'T00:00:00';end.value=until.toISOString().slice(0,10)+'T00:00:00';result.value=null}
async function readSource(id:unknown){if(typeof id!=='string')return;source.value=null;try{source.value=await api.get(`/api/v1/quarterly-performances/${encodeURIComponent(id)}/sources`)}catch(failure){await failed(failure)}}
</script>
<template><section><h1>运营分析</h1><p>按授权范围、统一期间和可核验截止比较；默认展示汇总，来源缺失会明确列出。金额采用原十进制结果。</p><div class="filter-tabs" aria-label="分析主题"><button v-for="key in (['cancellations','treatment-comparison','skill-slot-coverage','performance'] as Metric[])" :key="key" :aria-pressed="metric===key" @click="metric=key;changeMetric();if(key==='performance')previousQuarter();load()">{{names[key]}}</button></div><form @submit.prevent="load"><fieldset :disabled="busy"><legend>分析条件（时间为北京时间）</legend><label>分析指标<select v-model="metric" @change="changeMetric"><option v-for="(name,key) in names" :key="key" :value="key">{{name}}</option></select></label><label>期间起点（含）<input v-model="start" type="datetime-local" step="1" required></label><label>期间终点（不含）<input v-model="end" type="datetime-local" step="1" required></label><label>统一截止（带时区）<input v-model="cutoff" required></label><label>查看诊所<select v-model="clinic"><option value="">全部授权诊所</option><option v-for="c in catalogs.clinics" :key="c.id" :value="c.id">{{c.label}}</option></select></label><label v-if="['treatment-comparison','skill-slot-coverage','traceability'].includes(metric)">治疗项目<select v-model="treatment" :required="metric==='skill-slot-coverage'"><option value="">选择治疗项目</option><option v-for="t in catalogs.treatments" :key="t.id" :value="t.id">{{t.label}}</option></select></label><label v-if="!['coverage','calculation-time'].includes(metric)">牙医<select v-model="dentist"><option value="">全部授权牙医</option><option v-for="d in catalogs.dentists" :key="d.id" :value="d.id">{{d.label}}</option></select></label><button type="button" @click="previousQuarter">使用上一完整季度</button><button type="button" @click="updateCurrentCutoff">更新当前截止</button><button>查询分析</button></fieldset></form><p v-if="error" role="alert" class="error-message">{{error}}</p>
<section v-if="result" class="analysis-result" aria-label="分析结果"><h2>{{names[result.metric]}}</h2><p class="analysis-context">{{new Date(result.start).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}} 至 {{new Date(result.end).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}} · 截止 {{new Date(result.cutoff).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}}（北京时间） · 口径 A1a / B13</p><p v-if="result.provisional" role="status" class="provisional">暂定结果：含待处理预约、未发布人员或尚未结束的期间；请结合下列数量核对。</p><p v-if="result.not_computable_reason" role="status" class="unavailable">{{reasons[result.not_computable_reason]??result.not_computable_reason}}</p><div class="analysis-stats"><div><span>样本数</span><strong>{{result.sample_count}}</strong></div><div><span>排除数</span><strong>{{result.excluded_count}}</strong></div><div><span>缺失数</span><strong>{{result.missing_count}}</strong></div><div><span>未处理／未发布数</span><strong>{{result.unprocessed_count}}</strong></div></div>
<section v-if="result.value!==null" class="metric-value"><h3>{{ratioMetrics.has(result.metric)?'比例':result.metric==='treatment-comparison'?'加权单位价':result.metric==='calculation-time'?'工作日耗时':'记录数量'}}</h3><strong>{{ratioMetrics.has(result.metric)?percent(result.value):result.value}}</strong><div v-if="ratioMetrics.has(result.metric)" class="ratio-track" role="img" :aria-label="`比例 ${percent(result.value)}`"><div :style="{width:`${Math.min(100,Math.max(0,Number(result.value)*100))}%`}"></div></div></section>
<p v-if="result.metric==='cancellations'">仅统计截止时隙已结束队列，排除诊所原因取消及改约。待处理预约仍保留原状态，未视为到诊或自动爽约。</p><p v-if="result.metric==='skill-slot-coverage'">覆盖按全部必需资质及执业有效的正常时隙计算，与该时隙是否被预约占用无关。</p><p v-if="result.metric==='skill-structure'">此表为期间有效资质；拥有某项非必需资质，不等于符合某个治疗项目的全部必需条件。</p><p v-if="result.metric==='performance'">仅显示所选范围可比的当前已发布个人版本；应涵盖个人冻结来源的全部诊所，未发布和旧口径不混合比较。</p>
<div class="table-scroll"><table><caption>同口径分项结果</caption><thead><tr><th v-for="[key,title] in columns[result.metric]" :key="key">{{title}}</th><th v-if="result.metric==='performance' && sourceAllowed">授权来源</th></tr></thead><tbody><tr v-for="(row,index) in rows" :key="index"><td v-for="[key] in columns[result.metric]" :key="key">{{display(key,row[key])}}</td><td v-if="result.metric==='performance' && sourceAllowed"><button @click="readSource(row.quarterly_performance_id)">核对冻结来源</button></td></tr></tbody></table></div><details><summary>来源核验标识</summary><ul><li v-for="reference in result.source_references" :key="reference" class="source-reference">{{reference}}</li></ul></details></section>
<section v-if="source"><h2>经授权读取的季度冻结来源</h2><p>规则 {{source.rule_version}} · 截止 {{source.cutoff}}</p><FrozenSources :snapshot="source.source_snapshot"/><button @click="source=null">关闭来源</button></section></section></template>
<style scoped>fieldset{display:flex;gap:16px;flex-wrap:wrap;padding:20px;margin:20px 0}label{display:grid;gap:6px;min-width:200px}input,select{padding:9px;border:1px solid #bacdc5;border-radius:5px}button{padding:9px 14px}.analysis-stats{display:grid;grid-template-columns:repeat(4,minmax(120px,1fr));gap:16px;margin:20px 0}.analysis-stats>div{display:grid;padding:18px;border:1px solid #dce7e2;border-radius:7px}.analysis-stats strong{font-size:26px;margin-top:6px}.analysis-context{color:#52675d;font-size:13px;overflow-wrap:anywhere}.provisional,.unavailable{padding:14px;border-left:4px solid #c38421;background:#fff8e9}.metric-value{padding:20px;background:#f4f9f6}.metric-value>strong{font-size:36px;color:#186844}.ratio-track{height:12px;background:#dce9e1;border-radius:6px;overflow:hidden;max-width:500px}.ratio-track>div{height:100%;background:#27825a}.table-scroll{overflow:auto}table{width:100%;border-collapse:collapse;margin:24px 0;font-variant-numeric:tabular-nums}th,td{padding:12px 10px;border-bottom:1px solid #dce7e2;white-space:nowrap;text-align:left}th{background:#f5f9f7}.source-reference{overflow-wrap:anywhere;font-size:12px}pre{max-height:500px;overflow:auto;font-size:12px}@media(max-width:800px){.analysis-stats{grid-template-columns:repeat(2,1fr)}}</style>
